function simpleFormQuestionPrefersClaude(question) {
  const label = getQuestionLabel(question);
  const fieldNames = getQuestionFieldNames(question);
  const fieldTypes = getQuestionFieldTypes(question);
  const haystack = `${label} ${fieldNames.join(" ")} ${fieldTypes.join(" ")}`.toLowerCase();
  return /cover\s*letter|supporting statement|why.*(?:role|company|apply|interested)|motivation|tell us about|describe|explain|statement|additional notes|message/.test(haystack);
}

async function generateSimpleFormApplicationAnswerPlan(task, candidate = {}, schema = {}, provider = "simple_form") {
  const cvText = getCvText(task);
  const answers = { ...getApplicationAnswers(task) };
  const questions = getSchemaQuestions(schema)
    .filter((question) => {
      const label = `${getQuestionLabel(question)} ${getQuestionFieldNames(question).join(" ")}`;
      if (/cover[_\s-]*letter/i.test(label)) {
        return true;
      }
      return !isCoveredByCandidateData(
        question,
        candidate,
        Boolean(task.__sffc_cv_path || task.cv_file_url),
        Number(task.cover_letter_requested || 0) === 1
      );
    })
    .filter((question) => !hasAnswerForQuestion(question, answers));
  const generated = {};
  const items = [];
  const unresolved = [];
  const needsHuman = [];

  for (let index = 0; index < questions.length; index += 1) {
    const question = questions[index];
    if (teamtailorClaudeAnswersEnabled && getClaudeApiKey() && simpleFormQuestionPrefersClaude(question)) {
      unresolved.push({ index, question });
      continue;
    }
    const answer = getSimpleFormSyntheticAnswerForQuestion(question, answers, candidate, task);
    if (!answerHasValue(answer)) {
      unresolved.push({ index, question });
      continue;
    }
    const label = getQuestionLabel(question);
    const fieldNames = getQuestionFieldNames(question);
    const normalized = questionLooksChoiceBased(question)
      ? getBestChoiceLabel(answer, getQuestionChoiceLabels(question))
      : cleanText(answer);
    if (!answerHasValue(normalized)) {
      unresolved.push({ index, question });
      continue;
    }
    generated[label] = normalized;
    fieldNames.forEach((name) => {
      generated[name] = normalized;
      generated[String(name).toLowerCase()] = normalized;
    });
    items.push({ label, fieldNames, answer: normalized, source: "rule", confidence: 1 });
  }

  if (teamtailorClaudeAnswersEnabled && unresolved.length && getClaudeApiKey()) {
    const claude = await callClaudeJson(buildSimpleFormClaudeAnswerPrompt({
      task,
      candidate,
      cvText,
      questions: unresolved.map((entry) => entry.question),
      provider,
    }), {
      system: "You produce conservative JSON-only answers for job application form fields. Prefer needs_human over unsupported claims. Never invent candidate facts.",
      maxTokens: 4500,
      temperature: 0.1,
    }).catch((error) => ({ success: false, reason: error && error.message ? error.message : String(error), data: null }));

    const claudeAnswers = Array.isArray(claude?.data?.answers) ? claude.data.answers : [];
    for (const item of claudeAnswers) {
      const unresolvedEntry = unresolved[Number(item.index)];
      const answer = cleanText(item.answer || "");
      if (!unresolvedEntry || !answer || item.safe_to_use === false) {
        continue;
      }
      const question = unresolvedEntry.question;
      const label = getQuestionLabel(question);
      const fieldNames = getQuestionFieldNames(question);
      const normalized = /privacy|consent|declaration|terms|policy|personal\s+data|data\s+processing|confirm/i.test(label)
        ? "Yes"
        : questionLooksChoiceBased(question)
          ? getBestChoiceLabel(answer, getQuestionChoiceLabels(question))
          : answer;
      if (!answerHasValue(normalized)) {
        continue;
      }
      generated[label] = normalized;
      fieldNames.forEach((name) => {
        generated[name] = normalized;
        generated[String(name).toLowerCase()] = normalized;
      });
      items.push({
        label,
        fieldNames,
        answer: normalized,
        source: item.source || "claude",
        confidence: Number(item.confidence || 0),
      });
    }
    if (!claude?.success) {
      needsHuman.push({ reason: claude?.reason || "claude_unavailable" });
    }
    if (Array.isArray(claude?.data?.needs_human)) {
      needsHuman.push(...claude.data.needs_human);
    }
  } else if (unresolved.length && !getClaudeApiKey()) {
    needsHuman.push({ reason: "claude_missing_api_key", count: unresolved.length });
  }

  const mergedAnswers = { ...generated, ...answers };
  setTaskApplicationAnswers(task, mergedAnswers);
  return {
    generated_count: items.length,
    unresolved_count: Math.max(0, questions.length - items.length),
    claude_enabled: teamtailorClaudeAnswersEnabled,
    claude_available: Boolean(getClaudeApiKey()),
    items: items.slice(0, 80),
    needs_human: needsHuman.slice(0, 40),
  };
}

function workdayQuestionRequiresHumanAnswer(question) {
  const label = getQuestionLabel(question);
  const haystack = `${label} ${getQuestionFieldNames(question).join(" ")} ${getQuestionChoiceLabels(question).join(" ")}`.toLowerCase();
  return /transcript|certificate|certification number|licen[cs]e number|portfolio|writing sample|work sample|reference contact|passport|national insurance|social security|tax id|government id|exact grade|exact gpa|sat|act score|current salary|salary history/.test(haystack);
}

function getWorkdaySyntheticAnswerForQuestion(question, answers = {}, task = {}, candidate = {}) {
  const label = getQuestionLabel(question);
  const haystack = `${label} ${getQuestionFieldNames(question).join(" ")} ${getQuestionChoiceLabels(question).join(" ")}`.toLowerCase();
  const explicit = getAnswerForQuestion(question, answers);
  if (answerHasValue(explicit)) {
    return explicit;
  }
  const fallback = getWorkdayFieldFallbackAnswer(task, label, candidate);
  if (answerHasValue(fallback)) {
    return fallback;
  }
  const defaultChoices = getWorkdayDefaultAnswerForQuestion(label);
  if (questionLooksChoiceBased(question)) {
    return getBestChoiceLabel(defaultChoices[0] || "", getQuestionChoiceLabels(question)) || defaultChoices[0] || "";
  }
  if (/cover\s*letter|motivation|why.*(?:role|company|apply|interested)|interest in this position/.test(haystack)) {
    return "";
  }
  if (/if yes|provide details|additional details|explain/.test(haystack)) {
    return "N/A";
  }
  if (/notice period/.test(haystack)) {
    return "One month";
  }
  if (/available to start|start date|date available/.test(haystack)) {
    return getWorkdayDefaultAvailableStartDate();
  }
  if (/salary|compensation|bonus/.test(haystack)) {
    return getWorkdayCompensationAnswerForLabel(label);
  }
  return "";
}

