function getRandomBlackstoneBusinessGroupDefault() {
  const groups = ["Private Equity", "Credit", "Real Estate", "Infrastructure", "Blackstone Growth", "Tactical Opportunities"];
  return groups[Math.floor(Math.random() * groups.length)] || "Private Equity";
}

function getWorkdayDefaultAvailableStartDate() {
  const date = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);
  return [
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
    String(date.getFullYear()),
  ].join("/");
}

function getWorkdayTodayDate() {
  const date = new Date();
  return [
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0"),
    String(date.getFullYear()),
  ].join("/");
}

async function getWorkdayLocalizedTodayDate(page) {
  const locale = await page.evaluate(() => {
    const url = window.location.href || "";
    const htmlLang = document.documentElement?.getAttribute("lang") || "";
    const bodyText = String(document.body?.innerText || "").slice(0, 1200);
    return `${url} ${htmlLang} ${bodyText}`;
  }).catch(() => "");
  const date = new Date();
  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const year = String(date.getFullYear());
  if (/\/(?:en-GB|en-IE|fr-|de-|es-|it-|nl-|pt-)|\ben[-_ ]?gb\b|\benglish\s*\(united kingdom\)/i.test(locale)) {
    return [day, month, year].join("/");
  }
  return [month, day, year].join("/");
}

async function getWorkdayLocalizedDefaultAvailableStartDate(page) {
  const locale = await page.evaluate(() => {
    const url = window.location.href || "";
    const htmlLang = document.documentElement?.getAttribute("lang") || "";
    const bodyText = String(document.body?.innerText || "").slice(0, 1200);
    return `${url} ${htmlLang} ${bodyText}`;
  }).catch(() => "");
  const date = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);
  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const year = String(date.getFullYear());
  if (/\/(?:en-GB|en-IE|fr-|de-|es-|it-|nl-|pt-)|\ben[-_ ]?gb\b|\benglish\s*\(united kingdom\)/i.test(locale)) {
    return [day, month, year].join("/");
  }
  return [month, day, year].join("/");
}

function getWorkdayDateDigits(value = "") {
  return cleanText(value).replace(/\D/g, "").slice(0, 8);
}

function getWorkdayCompensationAnswerForLabel(label) {
  const text = cleanText(label).toLowerCase();
  if (/base salary|\bbonus\b|minimum annual/.test(text)) {
    return "1";
  }
  if (/monthly/.test(text)) {
    return "Negotiable";
  }
  return "Negotiable";
}

function getWorkdayAnswerValue(task, patterns, fallback = "") {
  const answers = getApplicationAnswers(task);
  return answerByPatterns(answers, patterns) || cleanText(fallback);
}

function getWorkdayPreferredLocationAliases(task, pageUrl = "") {
  const payload = getTaskPayload(task);
  const answers = getApplicationAnswers(task);
  const source = cleanText(
    answers["Preferred Location"] ||
      answers.Location ||
      answers.location ||
      payload.preferred_location ||
      payload.location ||
      task.location ||
      task.job_location ||
      pageUrl ||
      task.application_workspace_url ||
      task.application_url ||
      ""
  );
  const aliases = [];
  const lower = source.toLowerCase();
  const cityPatterns = [
    ["Charlotte", /\bcharlotte\b/],
    ["Austin", /\baustin\b/],
    ["Santa Monica", /\bsanta[ -]?monica\b/],
    ["New York", /\bnew[ -]?york\b/],
    ["London", /\blondon\b/],
    ["Dubai", /\bdubai\b/],
    ["Singapore", /\bsingapore\b/],
    ["Hong Kong", /\bhong[ -]?kong\b/],
    ["Boston", /\bboston\b/],
    ["Paris", /\bparis\b/],
    ["Zurich", /\bzurich\b/],
    ["Montreal", /\bmontr[eé]al\b/],
  ];
  for (const [label, pattern] of cityPatterns) {
    if (pattern.test(lower)) {
      aliases.push(label);
    }
  }
  if (!aliases.length) {
    aliases.push("Open to relocation", "Hybrid", "Office based", "Charlotte", "London", "Dubai");
  }
  aliases.push("Open to relocation", "Willing to relocate");
  return aliases.filter((value, index, list) => value && list.indexOf(value) === index);
}

function getWorkdayFieldFallbackAnswer(task, label, candidate = {}) {
  const lower = cleanText(label).toLowerCase();
  if (/salary|compensation|expected monthly basic salary|expected fixed compensation|base salary|\bbonus\b/.test(lower)) {
    return getWorkdayAnswerValue(task, [/salary/, /compensation/, /bonus/], getWorkdayCompensationAnswerForLabel(label));
  }
  if (/notice period|commence work/.test(lower)) {
    return getWorkdayAnswerValue(task, [/notice period/, /commence/], "One month");
  }
  if (/date available|preferred start date|available to start|when are you available|when would you be able|\bstart date\b/.test(lower)) {
    return getWorkdayAnswerValue(task, [/date available/, /preferred start date/, /available to start/, /start date/], getWorkdayDefaultAvailableStartDate());
  }
  if (/field of study|major|area of study/.test(lower)) {
    const education = extractWorkdayEducationEntriesFromCv(getCvText(task))[0] || {};
    return cleanText(education.fieldOfStudy || getWorkdayAnswerValue(task, [/field of study/, /major/], "Finance"));
  }
  if (/school or university|institution/.test(lower)) {
    const education = extractWorkdayEducationEntriesFromCv(getCvText(task))[0] || {};
    return cleanText(education.school || getWorkdayAnswerValue(task, [/school/, /university/, /institution/], "University"));
  }
  if (/overall result|gpa/.test(lower)) {
    const education = extractWorkdayEducationEntriesFromCv(getCvText(task))[0] || {};
    return cleanText(education.gradeAverage || getWorkdayAnswerValue(task, [/gpa/, /grade average/, /overall result/], "8/10"));
  }
  if (/sat|act score|combined score/.test(lower)) {
    return getWorkdayAnswerValue(task, [/sat/, /act score/, /combined score/], "N/A");
  }
  if (/if yes|provide details|please provide details|additional details|explain/.test(lower)) {
    return "N/A";
  }
  if (/phone number/.test(lower)) {
    const answers = getApplicationAnswers(task);
    return normalizePhoneForDialCode(answers["Phone Number"] || candidate.phone || "", answers["Country Phone Code"] || "");
  }
  return "";
}

async function clickWorkdayCheckboxesNearQuestion(page, patterns, aliases) {
  const sources = (patterns || []).map((pattern) => pattern.source || String(pattern)).filter(Boolean);
  const wanted = (Array.isArray(aliases) ? aliases : [aliases]).map(cleanText).filter(Boolean);
  if (!sources.length || !wanted.length) {
    return { found: false, filled: false, scope_text: "" };
  }
  return page.evaluate(
    ({ sources, wanted }) => {
      const clean = (value) => String(value || "").replace(/\s+/g, " ").trim();
      const compact = (value) => clean(value).toLowerCase().replace(/[^a-z0-9]+/g, "");
      const visible = (element) => {
        if (!element || element.disabled || element.getAttribute("aria-disabled") === "true") return false;
        const style = window.getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
      };
      const isChecked = (control) =>
        control.matches("input[type='checkbox']") ? Boolean(control.checked) : control.getAttribute("aria-checked") === "true";
      const labelFor = (control) => {
        const id = control.getAttribute("id") || "";
        const explicit = id && window.CSS?.escape ? document.querySelector(`label[for="${CSS.escape(id)}"]`) : null;
        const scope = explicit || control.closest("label") || control.closest("[role='checkbox']") || control.closest("li, div");
        return clean(`${explicit?.textContent || ""} ${scope?.textContent || ""} ${control.getAttribute("aria-label") || ""} ${control.value || ""}`);
      };
      const clickTargetFor = (control) => {
        const id = control.getAttribute("id") || "";
        const explicit = id && window.CSS?.escape ? document.querySelector(`label[for="${CSS.escape(id)}"]`) : null;
        return explicit || control.closest("label") || control.closest("[role='checkbox']") || control;
      };
      const regexes = sources.map((source) => new RegExp(source, "i"));
      const wantedCompacts = wanted.map(compact);
      const scopes = Array.from(document.querySelectorAll("fieldset, section, [role='group'], [data-automation-id*='formField'], div"))
        .filter(visible)
        .map((scope) => ({ scope, text: clean(scope.textContent || "") }))
        .filter((entry) => {
          if (!entry.text || /^errors?\s+(and alerts\s+)?found\b|^error[-:\s]/i.test(entry.text)) return false;
          return regexes.some((regex) => regex.test(entry.text)) && entry.scope.querySelector("input[type='checkbox'], [role='checkbox']");
        })
        .sort((a, b) => a.text.length - b.text.length);
      for (const { scope, text } of scopes.slice(0, 8)) {
        const target = Array.from(scope.querySelectorAll("input[type='checkbox'], [role='checkbox']"))
          .filter(visible)
          .map((control) => {
            const label = labelFor(control);
            const labelCompact = compact(label);
            const score = wantedCompacts.reduce((best, value) => {
              if (!value || !labelCompact) return best;
              if (labelCompact === value) return Math.max(best, 180);
              if (labelCompact.includes(value) || value.includes(labelCompact)) return Math.max(best, 130);
              return best;
            }, 0);
            return { control, label, score };
          })
          .filter((entry) => entry.score > 0)
          .sort((a, b) => b.score - a.score || a.label.length - b.label.length)[0];
        if (!target) continue;
        if (!isChecked(target.control)) {
          const clickTarget = clickTargetFor(target.control);
          clickTarget.scrollIntoView({ block: "center", inline: "nearest" });
          clickTarget.click();
          if (target.control.matches("input[type='checkbox']") && !target.control.checked) {
            const descriptor = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "checked");
            if (descriptor?.set) descriptor.set.call(target.control, true);
            else target.control.checked = true;
            target.control.dispatchEvent(new Event("input", { bubbles: true }));
            target.control.dispatchEvent(new Event("change", { bubbles: true }));
          }
        }
        return {
          found: true,
          filled: isChecked(target.control),
          scope_text: text.slice(0, 220),
          selected_label: target.label.slice(0, 160),
        };
      }
      return { found: false, filled: false, scope_text: scopes[0]?.text.slice(0, 220) || "" };
    },
    { sources, wanted }
  ).catch((error) => ({ found: false, filled: false, error: error?.message || String(error), scope_text: "" }));
}

async function repairWorkdayApplicationQuestionsPage(page, task) {
  const repairItems = buildWorkdayApplicationQuestionRepairItems(task);
  const selectOneSweepBefore = await repairVisibleWorkdaySelectOneQuestions(page).catch(() => ({
    attempted: 0,
    filled: 0,
    items: [],
  }));
  if (!repairItems.length) {
    return { attempted: selectOneSweepBefore.attempted || 0, filled: selectOneSweepBefore.filled || 0, items: selectOneSweepBefore.items || [] };
  }
  let filled = 0;
  const diagnostics = [
    ...(selectOneSweepBefore.items || []).map((item) => ({
      label: item.question || "visible_select_one",
      kind: "visible_select_one",
      answer_present: true,
      scope_found: true,
      filled: Boolean(item.filled),
      scope_text: cleanText(item.question || "").slice(0, 160),
      selected_label: (item.aliases || []).join(" / "),
    })),
  ];
  for (const item of repairItems) {
    if (item.kind === "text" && /^(date_available|salary_expectations|notice_period)$/i.test(item.label || "")) {
      diagnostics.push({
        label: item.label,
        kind: item.kind,
        answer_present: answerHasValue(item.answer),
        scope_found: false,
        filled: false,
        skipped: "defer_to_validation_repair",
      });
      continue;
    }
    const answer = item.label === "date_available"
      ? await getWorkdayLocalizedDefaultAvailableStartDate(page)
      : Array.isArray(item.answer) ? item.answer[0] : item.answer;
    let result = { found: false, filled: false, scope_text: "" };
    try {
      if (item.kind === "textarea") {
        result = await withTimeout(fillWorkdayTextareaByQuestionPatterns(page, item.patterns, answer), 5000, result);
      } else if (item.kind === "text") {
        result = await withTimeout(fillWorkdayTextByQuestionPatterns(page, item.patterns, answer), 5000, result);
      } else if (item.kind === "gender") {
        result = await withTimeout(selectWorkdayGenderDisclosure(page, item.answer), 7000, result);
      } else if (item.kind === "choice") {
        result = await withTimeout(selectWorkdayDropdownByQuestionPatterns(page, item.patterns, item.answer), 4500, result);
      } else if (item.kind === "checkbox") {
        result = await withTimeout(clickWorkdayCheckboxesByAnswer(page, item.answer), 5000, result);
      } else if (item.kind === "random_checkbox") {
        result = await withTimeout(clickWorkdayRandomCheckboxByQuestionPatterns(page, item.patterns, item.answer), 5000, result);
        if (!result.filled) {
          result = await withTimeout(clickWorkdayCheckboxesByAnswer(page, item.answer), 5000, result);
        }
      } else if (item.kind === "skills") {
        result = await withTimeout(fillWorkdaySkillsFields(page, item.answer), 10000, result);
      }
    } catch (error) {
      result = {
        found: Boolean(result.found),
        filled: false,
        error: error?.message || String(error),
        scope_text: result.scope_text || "",
      };
    }
    if (result.filled) {
      filled += 1;
    }
    diagnostics.push({
      label: item.label,
      kind: item.kind,
      answer_present: answerHasValue(item.answer),
      scope_found: Boolean(result.found),
      filled: Boolean(result.filled),
      scope_text: cleanText(result.scope_text || "").slice(0, 160),
      selected_text: result.selected_text || undefined,
      selected_label: result.selected_label || undefined,
      opener: result.opener || undefined,
      error: result.error || undefined,
    });
    await page.keyboard.press("Escape").catch(() => {});
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  const selectOneSweepAfter = await repairVisibleWorkdaySelectOneQuestions(page).catch(() => ({
    attempted: 0,
    filled: 0,
    items: [],
  }));
  diagnostics.push(
    ...(selectOneSweepAfter.items || []).map((item) => ({
      label: item.question || "visible_select_one_after",
      kind: "visible_select_one_after",
      answer_present: true,
      scope_found: true,
      filled: Boolean(item.filled),
      scope_text: cleanText(item.question || "").slice(0, 160),
      selected_label: (item.aliases || []).join(" / "),
    }))
  );
  return {
    attempted: repairItems.length + (selectOneSweepBefore.attempted || 0) + (selectOneSweepAfter.attempted || 0),
    filled: filled + (selectOneSweepBefore.filled || 0) + (selectOneSweepAfter.filled || 0),
    items: diagnostics,
  };
}

async function findWorkdayQuestionControl(page, patterns, kind) {
  const patternSources = (patterns || []).map((pattern) => pattern.source || String(pattern)).filter(Boolean);
  if (!patternSources.length) {
    return { element: null, scopeText: "" };
  }
  const handle = await page.evaluateHandle(
    ({ sources, kind: controlKind }) => {
      const clean = (value) => String(value || "").replace(/\s+/g, " ").trim();
      const visible = (element) => {
        if (!element) return false;
        const style = window.getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return (
          style.visibility !== "hidden" &&
          style.display !== "none" &&
          rect.width > 0 &&
          rect.height > 0 &&
          !element.disabled &&
          element.getAttribute("aria-disabled") !== "true"
        );
      };
      const rejectScopeText = (text) => /^errors and alerts found\b|^error[-\s]/i.test(clean(text));
      const regexes = sources.map((source) => new RegExp(source, "i"));
      const controls = Array.from(
        document.querySelectorAll("textarea, input:not([type='hidden']), button, [role='button'], [role='combobox'], [aria-haspopup='listbox']")
      ).filter(visible);
      const candidates = [];
      for (const control of controls) {
        const tag = control.tagName;
        const type = control.type || "";
        const ownText = clean(`${control.textContent || ""} ${control.value || ""} ${control.getAttribute("aria-label") || ""}`);
        if (controlKind === "textarea" && tag !== "TEXTAREA") {
          continue;
        }
        if (controlKind === "text" && !(tag === "INPUT" || tag === "TEXTAREA")) {
          continue;
        }
        if (controlKind === "text" && /^(hidden|file|radio|checkbox|submit|button)$/i.test(type)) {
          continue;
        }
        if (controlKind === "choice") {
          const choiceLike =
            control.getAttribute("role") === "combobox" ||
            control.getAttribute("aria-haspopup") === "listbox" ||
            /select|prompt|questionnaire/i.test(`${control.id || ""} ${control.name || ""} ${control.getAttribute("data-automation-id") || ""}`) ||
            /select one|choose|yes|no/i.test(ownText);
          if (!choiceLike || /^(file|radio|checkbox|submit)$/i.test(type)) {
            continue;
          }
        }
        let cursor = control;
        for (let depth = 0; cursor && depth < 10; depth += 1) {
          const text = clean(cursor.textContent || "");
          if (text && rejectScopeText(text)) {
            break;
          }
          if (text && regexes.some((regex) => regex.test(text))) {
            const hasSelect = /select one|choose|yes|no/i.test(text) || /select one|choose|yes|no/i.test(ownText);
            const hasTextarea = Boolean(cursor.querySelector("textarea")) || tag === "TEXTAREA";
            const fieldish =
              cursor.matches?.("[data-automation-id*='formField'], fieldset, [role='group']") ||
              /formField|form-field|questionnaire/i.test(`${cursor.className || ""} ${cursor.getAttribute("data-automation-id") || ""}`);
            const score =
              (fieldish ? 60 : 0) +
              (controlKind === "choice" && hasSelect ? 90 : 0) +
              (controlKind === "textarea" && hasTextarea ? 90 : 0) -
              Math.min(text.length / 50, 40) -
              depth;
            candidates.push({ control, scopeText: text, score });
            break;
          }
          cursor = cursor.parentElement;
        }
      }
      candidates.sort((a, b) => b.score - a.score);
      return candidates[0] || null;
    },
    { sources: patternSources, kind }
  );
  const propertyHandle = await handle.getProperty("control").catch(() => null);
  const element = propertyHandle?.asElement() || null;
  const scopeText = await handle.getProperty("scopeText").then((property) => property.jsonValue()).catch(() => "");
  if (propertyHandle && !element) {
    await propertyHandle.dispose().catch(() => {});
  }
  await handle.dispose().catch(() => {});
  return { element, scopeText };
}

async function fillWorkdayTextareaByQuestionPatterns(page, patterns, answer) {
  const value = cleanText(answer);
  if (!value) {
    return { found: false, filled: false, scope_text: "" };
  }
  const { element, scopeText } = await findWorkdayQuestionControl(page, patterns, "textarea");
  if (!element) {
    return { found: false, filled: false, scope_text: "" };
  }
  const filled = await fillInputHandleWithVerification(page, element, value).catch(() => false);
  await element.dispose().catch(() => {});
  return { found: true, filled: Boolean(filled), scope_text: scopeText };
}

async function fillWorkdayTextByQuestionPatterns(page, patterns, answer) {
  const value = cleanText(answer);
  if (!value) {
    return { found: false, filled: false, scope_text: "" };
  }
  const { element, scopeText } = await findWorkdayQuestionControl(page, patterns, "text");
  if (element) {
    const filled =
      (await fillWorkdayExactTextField(page, element, value).catch(() => false)) ||
      (await typeTextControl(page, element, { answer: value }).catch(() => false));
    await element.dispose().catch(() => {});
    if (filled) {
      return { found: true, filled: true, scope_text: scopeText };
    }
  }
  const fallback = await fillVisibleWorkdayTextNearQuestionPatterns(page, patterns, value).catch(() => ({
    found: false,
    filled: false,
    scope_text: scopeText || "",
  }));
  return {
    found: Boolean(element || fallback.found),
    filled: Boolean(fallback.filled),
    scope_text: fallback.scope_text || scopeText || "",
  };
}

async function fillWorkdayTextByExactVisibleLabel(page, label, answer) {
  const value = cleanText(answer);
  const labelText = cleanText(label).replace(/\*+$/, "");
  if (!value || !labelText) {
    return { found: false, filled: false, scope_text: "" };
  }
  const target = await page.evaluate(({ labelText }) => {
    const clean = (text) => String(text || "").replace(/\s+/g, " ").trim();
    const compact = (text) => clean(text).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const targetKey = compact(labelText);
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const fieldOk = (control) =>
      control &&
      visible(control) &&
      !/^(hidden|file|radio|checkbox|submit|button)$/i.test(control.type || "") &&
      !/email|password|phone|country phone code|given name|family name|address|postal|city|search/i.test(
        `${control.id || ""} ${control.name || ""} ${control.getAttribute("aria-label") || ""} ${control.getAttribute("placeholder") || ""}`
      );
    const insideErrorSummary = (element) => {
      let scope = element;
      for (let depth = 0; depth < 6 && scope; depth += 1) {
        const text = clean(scope.textContent || "");
        if (/^errors?\s+(and alerts\s+)?found\b|^error\s*-/i.test(text)) {
          return true;
        }
        scope = scope.parentElement;
      }
      return false;
    };
    const exactLabels = Array.from(document.querySelectorAll("label, [id*='label' i], [data-automation-id*='label' i], p, span, div"))
      .filter(visible)
      .map((element) => {
        const text = clean(element.textContent || "").replace(/\*+$/, "");
        const key = compact(text).replace(/required$/, "");
        return { element, text, key, rect: element.getBoundingClientRect() };
      })
      .filter((entry) => {
        if (!entry.text || insideErrorSummary(entry.element)) return false;
        if (entry.key === targetKey) return true;
        if (!entry.key.startsWith(targetKey)) return false;
        return entry.text.length <= labelText.length + 260;
      })
      .sort((a, b) => a.key.length - b.key.length || a.text.length - b.text.length);
    const allControls = Array.from(document.querySelectorAll("input:not([type='hidden']), textarea")).filter(fieldOk);
    for (const label of exactLabels.slice(0, 8)) {
      const forId = label.element.getAttribute?.("for") || "";
      const explicit = forId && window.CSS?.escape ? document.getElementById(forId) : null;
      if (fieldOk(explicit)) {
        explicit.setAttribute("data-sffc-workday-exact-text-target", "1");
        return { found: true, scope_text: label.text.slice(0, 220) };
      }
      const ariaTarget = allControls.find((control) => {
        const labelledBy = clean(control.getAttribute("aria-labelledby") || "");
        return labelledBy.split(/\s+/).some((id) => id && id === label.element.id);
      });
      if (fieldOk(ariaTarget)) {
        ariaTarget.setAttribute("data-sffc-workday-exact-text-target", "1");
        return { found: true, scope_text: label.text.slice(0, 220) };
      }
      const scope = label.element.closest("[data-automation-id*='formField'], fieldset, [role='group'], section, li") || label.element.parentElement;
      const scoped = scope ? Array.from(scope.querySelectorAll("input:not([type='hidden']), textarea")).filter(fieldOk) : [];
      if (scoped.length === 1) {
        scoped[0].setAttribute("data-sffc-workday-exact-text-target", "1");
        return { found: true, scope_text: label.text.slice(0, 220) };
      }
      const below = allControls
        .map((control) => {
          const rect = control.getBoundingClientRect();
          const verticalGap = rect.top - label.rect.bottom;
          const horizontalOverlap = Math.min(label.rect.right + 700, rect.right) - Math.max(label.rect.left - 20, rect.left);
          const sameScope = Boolean(scope && scope.contains(control));
          return {
            control,
            score:
              (sameScope ? 500 : 0) +
              (verticalGap >= -12 && verticalGap <= 190 ? 260 : 0) +
              (horizontalOverlap > 0 ? 140 : 0) +
              (control.tagName === "TEXTAREA" ? 20 : 0) -
              Math.abs(verticalGap) -
              Math.max(0, -horizontalOverlap),
          };
        })
        .filter((entry) => entry.score > 180)
        .sort((a, b) => b.score - a.score)[0]?.control;
      if (below) {
        below.setAttribute("data-sffc-workday-exact-text-target", "1");
        return { found: true, scope_text: label.text.slice(0, 220) };
      }
    }
    return { found: exactLabels.length > 0, scope_text: exactLabels[0]?.text.slice(0, 220) || "" };
  }, { labelText }).catch(() => ({ found: false, scope_text: "" }));
  if (!target?.found) {
    return { found: false, filled: false, scope_text: target?.scope_text || "" };
  }
  const field = await page.$("[data-sffc-workday-exact-text-target='1']").catch(() => null);
  if (!field) {
    return { found: true, filled: false, scope_text: target.scope_text || "" };
  }
  const filled =
    (await fillWorkdayExactTextField(page, field, value).catch(() => false)) ||
    (await fillInputHandleWithVerification(page, field, value).catch(() => false));
  await field.evaluate((element) => element.removeAttribute("data-sffc-workday-exact-text-target")).catch(() => {});
  await field.dispose().catch(() => {});
  return { found: true, filled: Boolean(filled), scope_text: target.scope_text || "" };
}

async function fillWorkdayInputAfterVisibleTextNode(page, label, answer, options = {}) {
  const value = cleanText(answer);
  const labelText = cleanText(label).replace(/\*+$/, "");
  if (!value || !labelText) {
    return { found: false, filled: false, scope_text: "" };
  }
  const typedValue = options.date ? getWorkdayDateDigits(value) : value;
  if (!typedValue) {
    return { found: false, filled: false, scope_text: "" };
  }
  const target = await page.evaluate(({ labelText }) => {
    const clean = (input) => String(input || "").replace(/\s+/g, " ").trim();
    const compact = (input) => clean(input).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const wanted = compact(labelText);
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const textNodes = [];
    const walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const text = clean(node.nodeValue || "");
        if (!text || text.length > 520) return NodeFilter.FILTER_REJECT;
        const key = compact(text).replace(/required$/, "");
        if (key === wanted || (key.startsWith(wanted) && text.length <= labelText.length + 80)) {
          return NodeFilter.FILTER_ACCEPT;
        }
        return NodeFilter.FILTER_REJECT;
      },
    });
    let node;
    while ((node = walker.nextNode())) {
      const parent = node.parentElement;
      if (!visible(parent)) continue;
      const rect = parent.getBoundingClientRect();
      textNodes.push({ element: parent, text: clean(node.nodeValue || ""), rect });
    }
    const labels = textNodes.sort((a, b) => Math.abs(a.text.length - labelText.length) - Math.abs(b.text.length - labelText.length) || a.rect.top - b.rect.top);
    const controls = Array.from(document.querySelectorAll("input:not([type='hidden']), textarea"))
      .filter(visible)
      .filter((field) => !/^(file|radio|checkbox|submit|button)$/i.test(field.type || ""))
      .filter((field) => !/email|password|phone|country phone code|given name|family name|address|postal|city|search/i.test(
        `${field.type || ""} ${field.id || ""} ${field.name || ""} ${field.getAttribute("aria-label") || ""} ${field.getAttribute("placeholder") || ""}`
      ))
      .map((field) => ({ field, rect: field.getBoundingClientRect(), current: clean(field.value || "") }));
    for (const labelEntry of labels.slice(0, 8)) {
      const nextLabelTop = textNodes
        .filter((entry) => entry.element !== labelEntry.element)
        .filter((entry) => entry.rect.top > labelEntry.rect.bottom + 4)
        .filter((entry) => {
          const overlap = Math.min(labelEntry.rect.right + 760, entry.rect.right) - Math.max(labelEntry.rect.left - 40, entry.rect.left);
          return overlap > 0;
        })
        .sort((a, b) => a.rect.top - b.rect.top)[0]?.rect.top || Number.POSITIVE_INFINITY;
      const candidate = controls
        .map((control) => {
          const verticalGap = control.rect.top - labelEntry.rect.bottom;
          const horizontalOverlap = Math.min(labelEntry.rect.right + 760, control.rect.right) - Math.max(labelEntry.rect.left - 40, control.rect.left);
          return {
            ...control,
            score:
              (verticalGap >= -8 && verticalGap <= 95 ? 420 : 0) +
              (control.rect.top < nextLabelTop - 3 ? 220 : -500) +
              (horizontalOverlap > 0 ? 170 : 0) +
              (control.rect.width >= 120 ? 60 : 0) -
              Math.abs(verticalGap) -
              Math.max(0, -horizontalOverlap),
          };
        })
        .filter((entry) => entry.score > 260)
        .sort((a, b) => b.score - a.score || a.rect.top - b.rect.top)[0];
      if (!candidate) continue;
      candidate.field.setAttribute("data-sffc-workday-text-node-target", "1");
      return { found: true, scope_text: labelEntry.text.slice(0, 220), current: candidate.current };
    }
    return { found: labels.length > 0, scope_text: labels[0]?.text.slice(0, 220) || "" };
  }, { labelText }).catch(() => ({ found: false, scope_text: "" }));
  if (!target?.found) {
    return { found: false, filled: false, scope_text: "" };
  }
  const field = await page.$("[data-sffc-workday-text-node-target='1']").catch(() => null);
  if (!field) {
    return { found: true, filled: false, scope_text: target.scope_text || "" };
  }
  const meta = await field.evaluate((element) => ({ tagName: element.tagName, type: element.type || "" })).catch(() => ({}));
  const ok = options.date
    ? await fillWorkdayDateInputBySelector(page, "[data-sffc-workday-text-node-target='1']", typedValue).catch(() => false)
    : /^textarea$/i.test(meta.tagName || "")
      ? await typeTextControl(page, field, { label, answer: typedValue }).catch(() => false)
      : await fillWorkdayExactTextField(page, field, typedValue).catch(() => false);
  const verified = await field.evaluate((element, expected) => {
    const actual = String(element.value || "").trim();
    if (String(expected || "").replace(/\D/g, "").length === 8) {
      return actual.replace(/\D/g, "") === String(expected || "").replace(/\D/g, "");
    }
    return actual === String(expected || "").trim();
  }, typedValue).catch(() => false);
  await field.evaluate((element) => element.removeAttribute("data-sffc-workday-text-node-target")).catch(() => {});
  await field.dispose().catch(() => {});
  return { found: true, filled: Boolean(ok || verified), scope_text: target.scope_text || "", previous_value: target.current || "" };
}

async function fillWorkdayPreferredNameTextarea(page, answer = "No") {
  const value = cleanText(answer) || "No";
  const target = await page.evaluate(() => {
    const clean = (input) => String(input || "").replace(/\s+/g, " ").trim();
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const textareas = Array.from(document.querySelectorAll("textarea"))
      .filter(visible)
      .map((textarea) => {
        const rect = textarea.getBoundingClientRect();
        const scope = textarea.closest("[data-automation-id*='formField'], fieldset, section, [role='group'], li, div") || textarea.parentElement;
        const scopeText = clean(scope?.textContent || "");
        const invalid = textarea.getAttribute("aria-invalid") === "true" || /required|must have a value|error/i.test(scopeText);
        return { textarea, rect, scopeText, invalid, value: clean(textarea.value || "") };
      })
      .filter((entry) =>
        /preferred name|i have a preferred name/i.test(entry.scopeText) ||
        (entry.invalid && !entry.value && /preferred name|i have a preferred name/i.test(clean(document.body?.innerText || "")))
      )
      .sort((a, b) => {
        const priority = (entry) => (entry.invalid ? 0 : 1) + (entry.value ? 2 : 0);
        return priority(a) - priority(b) || a.rect.top - b.rect.top;
      });
    const targetEntry = textareas[0];
    if (!targetEntry) {
      return { found: false, scope_text: "" };
    }
    targetEntry.textarea.setAttribute("data-sffc-workday-preferred-name-textarea", "1");
    return {
      found: true,
      scope_text: targetEntry.scopeText.slice(0, 260),
      previous_value: targetEntry.value,
    };
  }).catch(() => ({ found: false, scope_text: "" }));
  if (!target?.found) {
    return { found: false, filled: false, scope_text: "" };
  }
  const field = await page.$("[data-sffc-workday-preferred-name-textarea='1']").catch(() => null);
  if (!field) {
    return { found: true, filled: false, scope_text: target.scope_text || "" };
  }
  const filled = await typeTextControl(page, field, { label: "Preferred Name", answer: value }).catch(() => false);
  const verified = await field.evaluate((element, expected) => String(element.value || "").trim() === String(expected || "").trim(), value).catch(() => false);
  await field.evaluate((element) => element.removeAttribute("data-sffc-workday-preferred-name-textarea")).catch(() => {});
  await field.dispose().catch(() => {});
  return {
    found: true,
    filled: Boolean(filled || verified),
    scope_text: target.scope_text || "",
    previous_value: target.previous_value || "",
  };
}

async function fillWorkdayTextImmediatelyAfterLabel(page, label, answer) {
  const value = cleanText(answer);
  const labelText = cleanText(label).replace(/\*+$/, "");
  if (!value || !labelText) {
    return { found: false, filled: false, scope_text: "" };
  }
  const target = await page.evaluate(({ labelText }) => {
    const clean = (input) => String(input || "").replace(/\s+/g, " ").trim();
    const compact = (input) => clean(input).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const targetKey = compact(labelText);
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const isTextField = (element) =>
      element &&
      visible(element) &&
      /^(input|textarea)$/i.test(element.tagName || "") &&
      !/^(hidden|file|radio|checkbox|submit|button)$/i.test(element.type || "") &&
      !/email|password|phone|country phone code|given name|family name|address|postal|city|search/i.test(
        `${element.id || ""} ${element.name || ""} ${element.getAttribute("aria-label") || ""} ${element.getAttribute("placeholder") || ""}`
      );
    const looksLikeLabel = (element) => {
      const text = clean(element.textContent || "").replace(/\*+$/, "");
      if (!text || text.length > 220) return false;
      if (/^errors?\s+(and alerts\s+)?found\b|^error[-:\s]/i.test(text)) return false;
      return /[A-Za-z]/.test(text);
    };
    const labels = Array.from(document.querySelectorAll("label, [id*='label' i], [data-automation-id*='label' i], p, span, div"))
      .filter(visible)
      .filter(looksLikeLabel)
      .map((element) => {
        const text = clean(element.textContent || "").replace(/\*+$/, "");
        const key = compact(text).replace(/required$/, "");
        return { element, text, key, rect: element.getBoundingClientRect() };
      })
      .filter((entry) => {
        if (entry.key === targetKey) return true;
        return entry.key.startsWith(targetKey) && entry.text.length <= labelText.length + 80;
      })
      .sort((a, b) => Math.abs(a.text.length - labelText.length) - Math.abs(b.text.length - labelText.length) || a.rect.top - b.rect.top);
    const allControls = Array.from(document.querySelectorAll("input:not([type='hidden']), textarea")).filter(isTextField);
    const allLabelRects = Array.from(document.querySelectorAll("label, [id*='label' i], [data-automation-id*='label' i], p, span, div"))
      .filter(visible)
      .filter(looksLikeLabel)
      .map((element) => ({ element, rect: element.getBoundingClientRect(), text: clean(element.textContent || "") }));
    for (const labelEntry of labels.slice(0, 6)) {
      const forId = labelEntry.element.getAttribute?.("for") || "";
      const explicit = forId && window.CSS?.escape ? document.getElementById(forId) : null;
      if (isTextField(explicit)) {
        explicit.setAttribute("data-sffc-workday-after-label-target", "1");
        return { found: true, scope_text: labelEntry.text.slice(0, 220) };
      }
      const labelledControl = allControls.find((control) => {
        const ids = clean(control.getAttribute("aria-labelledby") || "").split(/\s+/).filter(Boolean);
        return ids.includes(labelEntry.element.id);
      });
      if (labelledControl) {
        labelledControl.setAttribute("data-sffc-workday-after-label-target", "1");
        return { found: true, scope_text: labelEntry.text.slice(0, 220) };
      }
      const sameColumnNextLabelTop = allLabelRects
        .filter((entry) => entry.element !== labelEntry.element)
        .filter((entry) => entry.rect.top > labelEntry.rect.bottom + 4)
        .filter((entry) => {
          const overlap = Math.min(labelEntry.rect.right + 760, entry.rect.right) - Math.max(labelEntry.rect.left - 40, entry.rect.left);
          return overlap > 0;
        })
        .sort((a, b) => a.rect.top - b.rect.top)[0]?.rect.top || Number.POSITIVE_INFINITY;
      const scope = labelEntry.element.closest("[data-automation-id*='formField'], [data-automation-id*='questionnaire'], fieldset, [role='group'], li");
      const scored = allControls
        .map((control) => {
          const rect = control.getBoundingClientRect();
          const verticalGap = rect.top - labelEntry.rect.bottom;
          const horizontalOverlap = Math.min(labelEntry.rect.right + 760, rect.right) - Math.max(labelEntry.rect.left - 40, rect.left);
          const sameScope = Boolean(scope && scope.contains(control));
          const beforeNextLabel = rect.top < sameColumnNextLabelTop - 4;
          return {
            control,
            score:
              (sameScope ? 380 : 0) +
              (verticalGap >= -10 && verticalGap <= 120 ? 360 : 0) +
              (beforeNextLabel ? 180 : -260) +
              (horizontalOverlap > 0 ? 140 : 0) +
              (rect.width >= 90 ? 60 : 0) -
              Math.abs(verticalGap) -
              Math.max(0, -horizontalOverlap),
          };
        })
        .filter((entry) => entry.score > 260)
        .sort((a, b) => b.score - a.score || a.control.getBoundingClientRect().top - b.control.getBoundingClientRect().top);
      const winner = scored[0]?.control || null;
      if (winner) {
        winner.setAttribute("data-sffc-workday-after-label-target", "1");
        return { found: true, scope_text: labelEntry.text.slice(0, 220) };
      }
    }
    return { found: labels.length > 0, scope_text: labels[0]?.text.slice(0, 220) || "" };
  }, { labelText }).catch(() => ({ found: false, scope_text: "" }));
  if (!target?.found) {
    return { found: false, filled: false, scope_text: "" };
  }
  const field = await page.$("[data-sffc-workday-after-label-target='1']").catch(() => null);
  if (!field) {
    return { found: true, filled: false, scope_text: target.scope_text || "" };
  }
  const filled =
    (await fillWorkdayExactTextField(page, field, value).catch(() => false)) ||
    (await fillInputHandleWithVerification(page, field, value).catch(() => false));
  await field.evaluate((element) => element.removeAttribute("data-sffc-workday-after-label-target")).catch(() => {});
  await field.dispose().catch(() => {});
  return { found: true, filled: Boolean(filled), scope_text: target.scope_text || "" };
}

async function fillWorkdayDateImmediatelyAfterLabel(page, label, answer) {
  const typedValue = getWorkdayDateDigits(answer);
  const expectedDigits = typedValue;
  const labelText = cleanText(label).replace(/\*+$/, "");
  if (!typedValue || !labelText) {
    return { found: false, filled: false, scope_text: "" };
  }
  const result = await fillWorkdayTextImmediatelyAfterLabel(page, label, typedValue);
  if (!result.found) {
    return result;
  }
  const matched = await page.evaluate(({ labelText, expectedDigits }) => {
    const clean = (input) => String(input || "").replace(/\s+/g, " ").trim();
    const compact = (input) => clean(input).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const targetKey = compact(labelText);
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const labels = Array.from(document.querySelectorAll("label, [id*='label' i], [data-automation-id*='label' i], p, span, div"))
      .filter(visible)
      .map((element) => {
        const text = clean(element.textContent || "").replace(/\*+$/, "");
        return { element, text, key: compact(text).replace(/required$/, ""), rect: element.getBoundingClientRect() };
      })
      .filter((entry) => entry.key === targetKey || (entry.key.startsWith(targetKey) && entry.text.length <= labelText.length + 90))
      .sort((a, b) => Math.abs(a.text.length - labelText.length) - Math.abs(b.text.length - labelText.length) || a.rect.top - b.rect.top);
    const controls = Array.from(document.querySelectorAll("input:not([type='hidden'])"))
      .filter(visible)
      .filter((field) => !/email|password|phone|country phone code|given name|family name|address|postal|city|search|file/i.test(
        `${field.type || ""} ${field.name || ""} ${field.id || ""} ${field.getAttribute("aria-label") || ""}`
      ));
    for (const labelEntry of labels.slice(0, 4)) {
      const candidate = controls
        .map((field) => {
          const rect = field.getBoundingClientRect();
          const verticalGap = rect.top - labelEntry.rect.bottom;
          const horizontalOverlap = Math.min(labelEntry.rect.right + 760, rect.right) - Math.max(labelEntry.rect.left - 40, rect.left);
          return {
            field,
            score:
              (verticalGap >= -10 && verticalGap <= 130 ? 300 : 0) +
              (horizontalOverlap > 0 ? 140 : 0) -
              Math.abs(verticalGap) -
              Math.max(0, -horizontalOverlap),
          };
        })
        .filter((entry) => entry.score > 120)
        .sort((a, b) => b.score - a.score)[0]?.field || null;
      if (!candidate) continue;
      const currentDigits = String(candidate.value || "").replace(/\D/g, "");
      if (currentDigits === expectedDigits) {
        return true;
      }
    }
    return false;
  }, { labelText, expectedDigits }).catch(() => false);
  return { ...result, filled: Boolean(result.filled || matched), typed_value: typedValue };
}

