async function fillWorkdayInvalidTextFieldByLabel(page, label, answer) {
  const value = cleanText(answer);
  const labelText = cleanText(label).replace(/\*+$/, "");
  if (!value || !labelText) {
    return { found: false, filled: false, scope_text: "" };
  }
  const target = await page.evaluate(({ labelText }) => {
    const clean = (text) => String(text || "").replace(/\s+/g, " ").trim();
    const compact = (text) => clean(text).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const targetKey = compact(labelText);
    const visible = (element) => {
      if (!element || element.disabled) return false;
      const style = window.getComputedStyle(element);
      const rect = element.getBoundingClientRect();
      return style.visibility !== "hidden" && style.display !== "none" && rect.width > 0 && rect.height > 0;
    };
    const fieldOk = (control) =>
      control &&
      visible(control) &&
      !/^(hidden|file|radio|checkbox|submit|button)$/i.test(control.type || "");
    const insideErrorSummary = (element) => {
      let scope = element;
      for (let depth = 0; depth < 6 && scope; depth += 1) {
        const text = clean(scope.textContent || "");
        if (/^errors?\s+(and alerts\s+)?found\b|^error\s*-/i.test(text)) {
          return true;
        }
        scope = scope.parentElement;
      }
      return false;
    };
    const scopeFor = (control) => {
      let scope = control;
      for (let depth = 0; depth < 10 && scope && scope.parentElement; depth += 1) {
        scope = scope.parentElement;
        const text = clean(scope.textContent || "");
        if (
          text &&
          compact(text).includes(targetKey) &&
          text.length <= 900 &&
          scope.querySelector("input:not([type='hidden']), textarea")
        ) {
          return scope;
        }
      }
      return control.closest("[data-automation-id*='formField'], fieldset, section, [role='group'], li, div") || control.parentElement;
    };
    const controls = Array.from(
      document.querySelectorAll("input[aria-invalid='true'], textarea[aria-invalid='true'], [class*='invalid' i] input, [class*='invalid' i] textarea")
    )
      .filter(fieldOk)
      .map((control) => {
        const scope = scopeFor(control);
        const scopeText = clean(scope?.textContent || "");
        const idish = clean(`${control.id || ""} ${control.name || ""} ${control.getAttribute("aria-label") || ""} ${control.getAttribute("placeholder") || ""}`);
        return { control, scopeText, idish };
      })
      .filter((entry) => !insideErrorSummary(entry.control) && entry.scopeText.length <= 900 && (compact(entry.scopeText).includes(targetKey) || compact(entry.idish).includes(targetKey)));
    const ranked = controls
      .map((entry) => ({
        ...entry,
        score:
          (compact(entry.scopeText).includes(targetKey) ? 500 : 0) +
          (compact(entry.idish).includes(targetKey) ? 250 : 0) -
          Math.min(entry.scopeText.length / 20, 150),
      }))
      .sort((a, b) => b.score - a.score);
    const selected = ranked[0];
    if (!selected) {
      return { found: false, scope_text: "" };
    }
    selected.control.setAttribute("data-sffc-workday-invalid-text-target", "1");
    return { found: true, scope_text: selected.scopeText.slice(0, 220) };
  }, { labelText }).catch(() => ({ found: false, scope_text: "" }));
  if (!target?.found) {
    return { found: false, filled: false, scope_text: target?.scope_text || "" };
  }
  const field = await page.$("[data-sffc-workday-invalid-text-target='1']").catch(() => null);
  if (!field) {
    return { found: true, filled: false, scope_text: target.scope_text || "" };
  }
  const filled =
    (await fillWorkdayExactTextField(page, field, value).catch(() => false)) ||
    (await fillInputHandleWithVerification(page, field, value).catch(() => false));
  await field.evaluate((element) => element.removeAttribute("data-sffc-workday-invalid-text-target")).catch(() => {});
  await field.dispose().catch(() => {});
  return { found: true, filled: Boolean(filled), scope_text: target.scope_text || "" };
}

